f = sp.sympify(expr_str, locals={
    'x': x, 't': t, 'pi': sp.pi, 'e': sp.E, 'E': sp.E,
    'sin': sp.sin, 'cos': sp.cos, 'tan': sp.tan,
    'exp': sp.exp, 'log': sp.log, 'ln': sp.log,
    'sqrt': sp.sqrt, 'abs': sp.Abs, 'Abs': sp.Abs
})

